<?php
namespace App\Features\Vehicles\Services;
use App\Features\Customers\Models\Customer; use App\Features\Vehicles\Models\Vehicle; use App\Features\Vehicles\Repositories\VehicleRepository; use App\Features\Vehicles\Repositories\VehicleTimelineRepository; use Illuminate\Support\Facades\DB;
class VehicleService { public function __construct(private VehicleRepository $vehicles, private VehicleTimelineRepository $timeline) {} public function create(array $data,string $tenantId,?string $actorId): Vehicle { return DB::transaction(function() use($data,$tenantId,$actorId){ Customer::where('tenant_id',$tenantId)->findOrFail($data['customer_id']); $data+=['tenant_id'=>$tenantId,'created_by'=>$actorId,'updated_by'=>$actorId]; $v=$this->vehicles->create($data); Customer::where('id',$v->customer_id)->increment('vehicles_count'); $this->record($v,$actorId,'vehicle.added','Vehicle Added','Vehicle master record was created.'); return $v->load('customer'); }); } public function update(Vehicle $vehicle,array $data,?string $actorId): Vehicle { return DB::transaction(function() use($vehicle,$data,$actorId){ Customer::where('tenant_id',$vehicle->tenant_id)->findOrFail($data['customer_id']); $before=$vehicle->toArray(); $oldCustomerId=$vehicle->customer_id; $data['updated_by']=$actorId; $v=$this->vehicles->update($vehicle,$data); if($oldCustomerId !== $v->customer_id){ Customer::where('id',$oldCustomerId)->decrement('vehicles_count'); Customer::where('id',$v->customer_id)->increment('vehicles_count'); } $this->record($v,$actorId,'vehicle.updated','Vehicle Updated','Vehicle master record was updated.',['before'=>$before,'after'=>$v->toArray()]); return $v; }); } public function bulkDelete(array $ids,string $tenantId): int { return DB::transaction(function() use($ids,$tenantId){ $vehicles=Vehicle::where('tenant_id',$tenantId)->whereIn('id',$ids)->get(['id','customer_id']); $deleted=$this->vehicles->bulkDelete($ids,$tenantId); foreach($vehicles->groupBy('customer_id') as $customerId=>$items){ Customer::where('id',$customerId)->decrement('vehicles_count',$items->count()); } return $deleted; }); } public function bulkUpdate(array $ids,string $tenantId,array $updates,?string $actorId): int { $updates['updated_by']=$actorId; return $this->vehicles->bulkUpdate($ids,$tenantId,$updates); } public function record(Vehicle $v,?string $actorId,string $type,string $title,string $description,array $metadata=[]): void { $this->timeline->record(['tenant_id'=>$v->tenant_id,'vehicle_id'=>$v->id,'actor_id'=>$actorId,'event_type'=>$type,'title'=>$title,'description'=>$description,'metadata'=>$metadata]); } }
